      "Confusing the plot summary (what happened) with the thematic message (what it means).",
      "Stating the theme as a single word or phrase instead of a full sentence.",
      "Overlooking implicit themes that are shown through subtext rather than explicitly stated by the narrator.",
      "Struggling to connect specific textual evidence to the abstract concept of the theme."
    ],
    "classroom_activity_design": {
      "warm_up": {
        "activity_name": "Topic vs. Theme Sort",
        "description": "Display a list of items on the board (mix of single words like 'War', 'Love' and sentences like 'War destroys innocence'). Students vote on which are topics and which are themes.",
        "time_allocation": "10 minutes"
      },
      "direct_instruction": {
        "activity_name": "The Theme Formula",
        "description": "Teacher models the process using a well-known story (e.g., 'The Tortoise and the Hare'). Demonstrate how to move from Plot -> Topic -> Theme Statement.",
        "time_allocation": "15 minutes"
      },
      "guided_practice": {
        "activity_name": "Collaborative Text Analysis",
        "description": "In small groups, students receive a short story excerpt. They must identify the theme and highlight three pieces of evidence that prove it exists in the text.",
        "time_allocation": "20 minutes"
      },
      "independent_practice": {
        "activity_name": "Theme Statement Draft",
        "description": "Students individually write a paragraph stating the theme of a provided text and explaining their reasoning using the evidence gathered.",
        "time_allocation": "10 minutes"
      },
      "closure": {
        "activity_name": "Exit Ticket Reflection",
        "description": "Students submit their theme statement and answer one reflection question: 'Why is identifying theme important for understanding literature?'",
        "time_allocation": "5 minutes"
      }
    },
    "required_resources": [
      "Whiteboard and markers",
      "Handout: Topic vs. Theme Sorting Cards",
      "Selection of 3-4 short stories or poems suitable for grade level",
      "Highlighters for text annotation",
      "Projector for displaying examples"
    ],
    "assessment_methods": [
      "Formative: Observation of student participation during the warm-up and guided practice.",
      "Summative: Evaluation of the Independent Practice paragraph using a rubric focusing on Accuracy, Evidence, and Clarity.",
