{
  "teaching_material": {
    "title": "Painting with Words: Understanding Similes and Metaphors",
    "subject": "English Language Arts",
    "knowledge_point": "Figurative Language: Similes and Metaphors",
    "target_audience": "Middle School (Grades 6-7)",
    "duration": "60 Minutes",
    "teaching_objectives": [
      "Students will be able to define simile and metaphor accurately.",
      "Students will be able to distinguish between similes and metaphors based on structural clues (use of 'like' or 'as').",
      "Students will be able to identify similes and metaphors within given texts.",
      "Students will be able to create original similes and metaphors to enhance descriptive writing."
    ],
    "key_points": [
      "Definition of Figurative Language: Language that uses words in non-literal ways to create effects.",
      "Simile: A comparison between two unlike things using 'like' or 'as'.",
      "Metaphor: A direct comparison between two unlike things stating one thing IS another (without 'like' or 'as').",
      "Purpose: To make descriptions more vivid, imaginative, and emotionally resonant."
    ],
    "difficulties": [
      "Confusion between literal comparisons and figurative language.",
      "Difficulty identifying implied metaphors where the connection is less obvious.",
      "Creating clichés instead of original imagery (e.g., 'busy as a bee').",
      "Understanding the deeper meaning behind the comparison rather than just the surface structure."
    ],
    "materials_needed": [
      "Whiteboard and markers",
      "Handout with short poems or paragraphs containing examples",
      "Index cards with nouns written on them (e.g., 'storm', 'silence', 'laughter')",
      "Projector/Screen for visual aids",
      "Student notebooks"
    ],
    "classroom_activity_design": [
      {
        "phase": "Warm-up (5 Minutes)",
        "activity_name": "Literal vs. Figurative Brainstorm",
        "description": "Write the sentence 'He is a rock' on the board. Ask students if he is literally made of stone. Discuss what qualities a rock has (strong, unchanging, cold) and apply them to the person. Introduce the concept of comparing things that aren't actually alike."
      },
      {
        "phase": "Direct Instruction (15 Minutes)",
        "activity_name": "The Detective's Guide",
        "description": "Present definitions and formulas:\n1. Simile Formula: Thing A + like/as + Thing B.\n2. Metaphor Formula: Thing A + is/are/was + Thing B.\nProvide 5 clear examples of each. Highlight keywords ('like', 'as', 'is', 'was'). Explain that metaphors often require more interpretation."
      },
      {
        "phase": "Guided Practice (15 Minutes)",
        "activity_name": "Sort the Sentences",
        "description": "Distribute a worksheet with 10 mixed sentences. Students work in pairs to label each as 'S' (Simile) or 'M' (Metaphor). Afterward, review answers as a class, asking students to explain WHY they chose that label (e.g., 'I saw the word like')."
      },
      {
        "phase": "Independent Practice (20 Minutes)",
        "activity_name": "The Imagery Challenge",
        "description": "Draw a noun from a hat (e.g., 'Time', 'Fear', 'Joy'). Students must write one simile and one metaphor describing that noun. Encourage them to avoid common clichés. Share 3-4 examples with the class for feedback."
      },
      {
        "phase": "Closure (5 Minutes)",
        "activity_name": "Exit Ticket",
        "description": "Students write one sentence on a slip of paper using either a simile or a metaphor to describe their mood today. Collect as they leave."
      }
    ],
    "assessment_methods": [
      "Formative: Observation during pair work and discussion.",
      "Formative: Accuracy of the 'Sort the Sentences' worksheet.",
      "Summative: Quality and accuracy of the 'Imagery Challenge' writing task.",
      "Exit Ticket: Quick check for individual understanding."
    ],
    "differentiation_strategies": [
      "For Struggling Learners: Provide a reference sheet with the formulas and keyword lists. Allow them to choose from a list of pre-selected nouns for the writing task.",
      "For Advanced Learners: Challenge them to write an extended metaphor (a paragraph where the comparison continues throughout) or analyze a complex poem excerpt."
    ],
    "examples_for_reference": {
      "similes": [
        "Her smile was as bright as the sun.",
        "He runs like the wind.",
        "The water felt like ice."
      ],
      "metaphors": [
        "Her smile was the sun.",
        "He is a wind runner.",
        "The classroom was a zoo."
      ]
    }
  }
}

