      {
        "category": "Knowledge",
        "goal": "Students will be able to state Newton's Third Law of Motion accurately."
      },
      {
        "category": "Skills",
        "goal": "Students will be able to identify action-reaction force pairs in various physical scenarios."
      },
      {
        "category": "Application",
        "goal": "Students will be able to explain everyday phenomena (e.g., walking, swimming, rocket propulsion) using the Third Law."
      },
      {
        "category": "Critical Thinking",
        "goal": "Students will distinguish between action-reaction pairs and balanced forces acting on a single object."
      }
    ],
    "key_points": [
      "Forces always exist in pairs; there is no such thing as an isolated force.",
      "The action force and reaction force are equal in magnitude.",
      "The action force and reaction force are opposite in direction.",
      "The action force and reaction force act on two different objects simultaneously.",
      "The nature of the forces in an action-reaction pair is the same (e.g., both gravitational, both contact)."
    ],
    "difficulties_and_misconceptions": [
      {
        "misconception": "Confusion with Balanced Forces",
        "explanation": "Students often confuse action-reaction pairs with balanced forces (equilibrium). It must be emphasized that action-reaction forces act on different objects, whereas balanced forces act on the same object."
      },
      {
        "misconception": "Motion Paradox",
        "explanation": "Students may ask, 'If forces are equal and opposite, why does anything move?' The explanation lies in analyzing the net force on individual objects, not the system as a whole."
      },
      {
        "misconception": "Sequence of Events",
        "explanation": "Students may think action happens before reaction. It must be clarified that they occur simultaneously."
      }
    ],
    "teaching_methods": [
      "Inquiry-based Learning",
      "Demonstration",
      "Collaborative Group Work",
      "Concept Mapping"
    ],
    "classroom_activity_design": [
      {
        "phase": "Introduction (5 mins)",
        "activity_name": "The Wall Push",
        "description": "Ask a student to stand on a skateboard (or smooth floor) and push against a stationary wall. Observe the student moving backward.",
        "purpose": "To create cognitive conflict and introduce the concept that pushing something results in being pushed back."
      },
      {
        "phase": "Exploration (15 mins)",
        "activity_name": "Spring Scale Tug-of-War",
        "description": "In pairs, students connect two spring scales together. They pull against each other gently, then harder. They record the readings on both scales simultaneously.",
        "purpose": "To empirically verify that the forces measured are equal in magnitude regardless of who pulls harder."
      },
      {
        "phase": "Explanation (10 mins)",
        "activity_name": "Formalizing the Law",
        "description": "Teacher presents the formal definition: 'For every action, there is an equal and opposite reaction.' Use diagrams to show vectors acting on Object A and Object B separately.",
        "purpose": "To solidify theoretical understanding and address the 'different objects' key point."
      },
      {
        "phase": "Elaboration (10 mins)",
        "activity_name": "Real-World Analysis",
        "description": "Groups analyze scenarios: Walking (foot pushes ground, ground pushes foot), Swimming (hand pushes water, water pushes swimmer), Rocket Launch (gas pushes down, rocket goes up).",
        "purpose": "To apply knowledge to complex systems and correct misconceptions about motion."
      },
      {
        "phase": "Evaluation (5 mins)",
        "activity_name": "Exit Ticket",
        "description": "Students answer: 'A bug hits a car windshield. Which force is greater: the bug on the car or the car on the bug? Explain why the bug splatters but the car doesn't slow down noticeably.'",
        "purpose": "To assess understanding of force equality versus acceleration differences (linking to Newton's Second Law)."
      }
    ],
    "required_resources": [
      "Skateboard or low-friction chair",
      "Two spring scales per group",
      "Whiteboard and markers",
      "Projector for diagrams",
      "Handouts with scenario diagrams"
    ],
    "assessment_criteria": [
      "Accuracy in identifying action-reaction pairs.",
      "Ability to articulate that forces act on different objects.",
      "Correct application of the law to explain motion.",
      "Participation in group discussions and experiments."
    ]
  }
}

