      {
        "phase": "Warm-up / Engagement",
        "time": "5 minutes",
        "description": "Display three items: an ice cube, a glass of water, and a balloon filled with air. Ask students: 'What do these have in common? How are they different?' Introduce the term 'Matter'."
      },
      {
        "phase": "Exploration / Group Work",
        "time": "15 minutes",
        "description": "Divide students into groups. Provide trays with items (stone, spoon, juice, cooking oil, empty plastic bag). Students manipulate items to test if they hold shape or flow, then sort them into three categories."
      },
      {
        "phase": "Explanation / Direct Instruction",
        "time": "10 minutes",
        "description": "Teacher uses a whiteboard chart to summarize findings. Introduce simple particle models (tightly packed for solids, sliding for liquids, flying apart for gases) to explain the observed behaviors."
      },
      {
        "phase": "Elaboration / Experiment",
        "time": "10 minutes",
        "description": "Demonstration: Pour water from a tall cup to a wide bowl to show shape change. Squeeze an inflated balloon to show gas compressibility. Discuss how steam from boiling water represents gas."
      },
      {
        "phase": "Evaluation / Closure",
        "time": "5 minutes",
        "description": "Exit Ticket: Students write down one example of a solid, liquid, and gas found in the classroom and explain one property for each."
      }
