      "Water and transparent cups",
      "Balloons",
      "Various household objects (spoon, oil, sponge, book)",
      "Whiteboard and markers",
      "Sorting worksheets",
      "Exit ticket slips"
    ],
    "assessment_criteria": [
      "Accuracy in classifying objects into solid, liquid, or gas categories.",
      "Ability to verbally explain why an object belongs to a specific state based on shape and volume.",
      "Active participation and collaboration during group sorting activities."
    ]
