{
  "topic": "Electromagnetic Induction",
  "subject": "Physics",
  "target_audience": "High School Students (Grade 11-12)",
  "estimated_duration": "45 minutes",
  "teaching_objectives": {
    "knowledge_and_skills": [
      "Understand the phenomenon of electromagnetic induction.",
      "Grasp the conditions required to generate an induced current.",
      "Master Faraday's Law of Electromagnetic Induction (formula and meaning).",
      "Apply Lenz's Law to determine the direction of induced current."
    ],
    "process_and_methods": [
      "Experience the scientific inquiry process through observation and experimentation.",
      "Learn to analyze physical phenomena using the concept of magnetic flux change."
    ],
    "emotional_attitude_and_values": [
      "Appreciate the symmetry and unity between electricity and magnetism.",
      "Cultivate rigorous scientific attitudes and exploration spirit."
    ]
  },
  "key_points_and_difficulties": {
    "key_points": [
      "The condition for generating induced current (change in magnetic flux).",
      "Faraday's Law of Electromagnetic Induction.",
      "Judging the direction of induced current using Lenz's Law."
    ],
    "difficulties": [
      "Deep understanding of 'magnetic flux change' (\u0394\u03a6).",
      "Flexible application of Lenz's Law in complex scenarios (e.g., conductor cutting magnetic field lines).",
      "Distinguishing between induced electromotive force and induced current."
    ]
  },
  "teaching_methods": [
    "Inquiry-based Learning",
    "Demonstration Experiment",
    "Discussion and Analysis",
    "Problem Solving"
  ],
  "classroom_activity_design": [
