    "Students will differentiate between convergent, divergent, and transform boundaries.",
    "Students will demonstrate understanding of earthquake safety protocols."
  ],
  "key_points": [
    "The Earth's crust is divided into moving tectonic plates floating on the mantle.",
    "Earthquakes primarily occur at plate boundaries due to stress accumulation and sudden release.",
    "Three types of plate interactions: Convergent (colliding), Divergent (separating), Transform (sliding)."
  ],
  "difficulties": [
    "Visualizing three-dimensional plate movements from two-dimensional maps.",
    "Understanding the concept of 'elastic rebound' during fault slip.",
    "Distinguishing between earthquake magnitude (energy released) and intensity (damage caused)."
  ],
  "classroom_activity_design": {
    "phase_1_warm_up": {
      "activity_name": "World Puzzle Prediction",
      "description": "Display a map of the world with plate boundaries overlaid. Ask students to predict where earthquakes happen most frequently based on coastlines and mountain ranges before revealing the data.",
      "time": "10 minutes"
    },
    "phase_2_main_inquiry": {
      "activity_name": "Edible Boundary Simulation",
      "description": "Use graham crackers and frosting to simulate plate movements. Students push crackers together (convergent), pull apart (divergent), and slide past each other (transform) to observe 'earthquake' effects (cracking/frosting displacement).",
      "time": "25 minutes"
    },
    "phase_3_application": {
      "activity_name": "Seismic Data Correlation",
      "description": "Provide a simplified map showing recent earthquake epicenters. Students mark them and compare with the plate boundary map to confirm correlations scientifically.",
      "time": "15 minutes"
    },
    "phase_4_closure": {
      "activity_name": "Safety Drill Discussion",
      "description": "Brief discussion and practice of 'Drop, Cover, and Hold On' procedure relevant to living in seismically active zones.",
      "time": "10 minutes"
    }
  },
  "assessment_methods": [
    "Exit ticket: Draw and label one type of plate boundary and explain where earthquakes occur.",
    "Observation of participation and accuracy during the cracker simulation.",
    "Short quiz on terminology (lithosphere, fault, epicenter, focus)."
  ],
  "resources_needed": [
    "Projector and presentation slides",
    "World map with plate boundaries",
    "Graham crackers, frosting, paper plates",
    "Recent earthquake data printouts",
    "Safety video clip"
  ]
}

