{
  "title": "Plate Tectonics and Continental Drift",
  "subject": "Earth Science / Geography",
  "target_audience": "Middle School / High School (Grades 7-10)",
  "duration": "90 Minutes (2 Class Periods)",
  "teaching_objectives": [
