{
  "teaching_material": {
    "title": "The Riemann Hypothesis and Its Implications in Number Theory",
    "target_audience": "Advanced Undergraduate Mathematics Students",
    "duration": "90 minutes",
    "teaching_objectives": [
      "Students will understand the definition and properties of the Riemann Zeta function.",
      "Students will be able to state the Riemann Hypothesis precisely.",
      "Students will comprehend the relationship between the zeros of the Zeta function and the distribution of prime numbers.",
      "Students will appreciate the historical significance and current status of the hypothesis."
    ],
    "key_points": [
      "Definition of the Riemann Zeta function: \\( \\zeta(s) = \\sum_{n=1}^{\\infty} \\frac{1}{n^s} \\) for Re(s) > 1.",
      "Analytic continuation of \\( \\zeta(s) \\) to the entire complex plane (except s=1).",
      "Distinction between trivial zeros (negative even integers) and non-trivial zeros.",
      "Statement of the Riemann Hypothesis: All non-trivial zeros lie on the critical line Re(s) = 1/2.",
      "Connection to the Prime Number Theorem and error terms in prime counting."
    ],
    "difficulties": [
      "Understanding complex analysis concepts such as meromorphic functions and analytic continuation.",
      "Grasping the intuition behind why the location of zeros affects prime distribution.",
      "Comprehending the depth of the implication (i.e., why it is considered one of the most important open problems)."
    ],
    "classroom_activity_design": [
      {
        "phase": "Introduction (15 mins)",
        "activity": "Historical Context & Prime Patterns",
        "description": "Briefly discuss the history of prime numbers from Euclid to Gauss. Show a plot of the prime counting function \\( \\pi(x) \\) versus the logarithmic integral \\( Li(x) \\). Ask students to observe the fluctuations."
      },
      {
        "phase": "Core Concept Lecture (30 mins)",
        "activity": "The Zeta Function Journey",
        "description": "Explain the Euler Product Formula connecting primes and \\( \\zeta(s) \\). Introduce the concept of analytic continuation without heavy proof. Visualize the 'Critical Strip' (0 < Re(s) < 1)."
      },
      {
        "phase": "Interactive Exploration (30 mins)",
        "activity": "Zero Hunting Simulation",
        "description": "Using pre-prepared Python/Matlab scripts, students visualize the magnitude of \\( \\zeta(s) \\) along the critical line. They identify approximate locations of the first few non-trivial zeros (e.g., at t ≈ 14.13, 21.02)."
      },
      {
        "phase": "Discussion & Implications (15 mins)",
        "activity": "Why Does It Matter?",
        "description": "Group discussion on the consequences of RH being true or false. Touch upon cryptography (RSA security relies on difficulty of factoring, though not directly RH, the distribution of primes is foundational) and random matrix theory."
      }
    ],
    "assessment": [
      {
        "type": "Concept Check",
        "question": "What is the difference between a trivial zero and a non-trivial zero of the Riemann Zeta function?"
      },
      {
        "type": "Short Answer",
        "question": "In your own words, explain how the Riemann Hypothesis relates to the accuracy of the Prime Number Theorem."
      },
      {
        "type": "Reflection",
        "question": "Why do you think the Riemann Hypothesis has remained unproven for over 160 years despite significant computational verification?"
      }
    ],
    "resources": [
      "Book: 'Riemann's Zeta Function' by H.M. Edwards",
      "Video: 'The Riemann Hypothesis' by Numberphile (YouTube)",
      "Software: Python library 'mpmath' for plotting Zeta function",
      "Website: The Clay Mathematics Institute Millennium Prize Problems page"
    ]
  }
}

{
  "course_info": {
    "title": "代数拓扑基础：基本群 (The Fundamental Group)",
    "knowledge_point": "Algebraic Topology: Fundamental Group",
    "duration": "2-3 课时 (90-135 分钟)",
    "target_audience": "数学系高年级本科生或研究生一年级"
  },
  "teaching_objectives": [
    "理解路径、回路及路径同伦的几何直观与严格定义。",
    "掌握基本群 π₁(X, x₀) 的定义及其群结构（单位元、逆元、结合律）。",
    "理解连续映射诱导的同态性质（函子性）。",
    "能够计算常见空间（如圆 S¹、球面 S²、环面 T²）的基本群。",
    "利用基本群区分不同胚的拓扑空间（例如平面挖去一点与三维空间挖去一点的区别）。"
  ],
  "key_points": [
    "路径同伦 (Path Homotopy) 的概念与等价关系。",
    "基本群的群运算定义：路径拼接 (Concatenation)。",
    "基本群运算的良定性 (Well-definedness)，即不依赖于代表元的选取。",
    "圆周的基本群 π₁(S¹) ≅ ℤ 的结论及其几何意义（绕数）。",
    "Van Kampen 定理的基本思想与应用场景。"
  ],
  "difficulties": [
    "抽象概念的理解：从几何直观到代数结构的转化。",
    "证明细节：验证群公理（特别是结合律在同伦类中的成立）的技术性证明。",
    "基点依赖性：理解当空间道路连通时，不同基点的基本群是同构的，但非典范同构。",
    "π₁(S¹) ≅ ℤ 的证明思路：提升定理 (Lifting Property) 的应用较为抽象。",
    "区分自由同伦 (Free Homotopy) 与固定端点同伦 (Path Homotopy)。"
  ],
  "classroom_activities": [
    {
