{
  "teaching_material": {
    "title": "Quantum Chemistry: Time-Independent Perturbation Theory",
    "knowledge_point": "Perturbation Theory",
    "target_audience": "Undergraduate Students (Physical Chemistry / Quantum Mechanics)",
    "estimated_duration": "90 minutes",
    "teaching_objectives": [
      "Understand the fundamental motivation for using perturbation theory in quantum chemistry (solving complex systems via approximations).",
      "Master the mathematical formulation of non-degenerate time-independent perturbation theory up to first order.",
      "Derive and interpret the first-order energy correction formula: E_n^(1) = <ψ_n^(0)|H'|ψ_n^(0)>.",
      "Apply the theory to simple model systems, such as a particle in a box with a potential step or a harmonic oscillator with an anharmonic term.",
      "Recognize the limitations of the method, including convergence issues and the necessity of degenerate perturbation theory."
    ],
    "key_points": [
      "Hamiltonian Partitioning: Splitting the total Hamiltonian into a solvable part (H_0) and a perturbation (H').",
      "The Perturbation Parameter (λ): Introducing a small parameter to track the order of approximation.",
      "Series Expansion: Expanding both energy eigenvalues and eigenfunctions as power series in λ.",
      "First-Order Energy Correction: The expectation value of the perturbation Hamiltonian with respect to the unperturbed wavefunction.",
      "First-Order Wavefunction Correction: Mixing of unperturbed states weighted by energy denominators."
    ],
    "difficulties": [
      "Mathematical Rigor: Following the derivation steps involving orthogonality conditions and normalization.",
      "Physical Interpretation: Understanding why the first-order energy correction is simply the average effect of the perturbation.",
      "Degeneracy: Distinguishing when non-degenerate theory fails and requiring degenerate perturbation theory.",
      "Convergence: Understanding that the perturbation series may not converge if the perturbation is too large."
    ],
    "prerequisites": [
      "Linear Algebra (Eigenvalues and Eigenvectors)",
      "Basic Quantum Mechanics (Schrödinger Equation, Hermitian Operators)",
      "Standard Model Systems (Particle in a Box, Harmonic Oscillator, Hydrogen Atom)"
    ],
    "classroom_activity_design": {
