    "key_points": [
      {
        "stage": "Light-dependent Reactions",
        "location": "Thylakoid Membranes",
        "inputs": [
          "Light Energy",
          "Water (H2O)",
          "NADP+",
          "ADP + Pi"
        ],
        "outputs": [
          "Oxygen (O2)",
          "ATP",
          "NADPH"
        ],
        "core_process": "Conversion of light energy into chemical energy stored in ATP and NADPH; Photolysis of water releases oxygen."
      },
      {
        "stage": "Light-independent Reactions (Calvin Cycle)",
        "location": "Stroma",
        "inputs": [
          "Carbon Dioxide (CO2)",
          "ATP",
          "NADPH"
        ],
        "outputs": [
          "Glyceraldehyde-3-phosphate (G3P/Sugar)",
          "ADP + Pi",
          "NADP+"
