    },
    {
      "phase": "Interactive Practice (25 mins)",
      "activity": "Human BST",
      "description": "Select 5-7 students to stand in front of the class holding number cards. Assign one as 'Root'. Have other students position themselves based on the BST property relative to existing students. Classmates verify correctness."
    },
    {
      "phase": "Coding Workshop (25 mins)",
