{
  "course_title": "微观经济学进阶：一般均衡理论",
  "topic": "General Equilibrium Theory",
  "target_audience": "经济学专业本科高年级或研究生一年级学生",
  "duration": "90 分钟",
  "teaching_objectives": [
    "理解一般均衡理论与局部均衡理论的核心区别",
    "掌握纯交换经济中的一般均衡条件及埃奇沃思框图的应用",
    "深入理解瓦尔拉斯法则及其在均衡分析中的作用",
    "能够阐述并解释福利经济学第一和第二基本定理",
    "培养从整体市场视角分析政策冲击（如税收）的能力"
  ],
  "key_points": [
    "一般均衡的定义：所有市场同时达到供求平衡的状态",
    "瓦尔拉斯均衡（Walrasian Equilibrium）的概念",
    "帕累托效率（Pareto Efficiency）与契约曲线",
    "瓦尔拉斯法则（Walras' Law）：n 个市场中 n-1 个市场出清意味着第 n 个市场也出清",
    "福利经济学两大定理：竞争均衡是帕累托有效的；任何帕累托有效配置都可以通过竞争均衡实现"
  ],
  "difficulties": [
    "数学证明的严谨性：一般均衡存在性的证明涉及不动点定理，对本科生较难",
    "市场间相互依赖性的直观理解：一个市场的价格变动如何传导至其他市场",
    "区分效率与公平：理解一般均衡理论主要关注资源配置效率而非收入分配",
    "动态调整过程：理解从非均衡到均衡的价格调整机制（如瓦尔拉斯拍卖人假设）"
  ],
  "classroom_activity_design": [
    {
      "phase": "导入环节 (10 分钟)",
      "activity": "对比案例讨论",
      "description": "展示两个案例：1. 仅分析小麦市场的供需变化（局部均衡）；2. 分析小麦价格上涨如何影响玉米市场和面包市场（一般均衡）。引导学生讨论为何需要一般均衡视角。"
    },
    {
      "phase": "核心概念讲解 (30 分钟)",
      "activity": "埃奇沃思框图演示",
      "description": "使用多媒体动画演示两人两种商品的交换过程。展示初始禀赋点、预算线移动以及最终达到契约曲线的过程。强调边际替代率相等（MRS_A = MRS_B）作为均衡条件。"
    },
    {
      "phase": "互动模拟 (25 分钟)",
      "activity": "模拟交易市场",
      "description": "将学生分为若干小组，每组代表不同消费者，持有不同的初始资源卡片。设定一组价格，让学生进行自愿交易。记录交易后的结果，验证是否达到帕累托改进，并讨论价格调整如何引导市场出清。"
    },
    {
      "phase": "深化与讨论 (15 分钟)",
      "activity": "政策辩论",
      "description": "提出议题：'对汽油征税的影响'。要求学生不仅考虑汽油市场，还要考虑汽车市场、公共交通市场及劳动力市场。分组讨论一般均衡效应与局部均衡效应的差异。"
    },
    {
      "phase": "总结与答疑 (10 分钟)",
      "activity": "知识梳理",
      "description": "回顾福利经济学两大定理，解答学生在模拟活动中遇到的关于价格机制的问题。"
    }
  ],
  "assessment_methods": [
    {
      "type": "随堂测验",
      "content": "5 道选择题，考察瓦尔拉斯法则和帕累托最优的定义。"
    },
    {
      "type": "课后作业",
      "content": "计算题：给定效用函数和初始禀赋，求解竞争性均衡价格和配置。"
    },
    {
      "type": "小论文",
      "content": "论述题：结合现实经济现象，分析一般均衡理论在评估贸易政策时的局限性。"
    }
  ],
  "recommended_resources": [
    "教材：哈尔·范里安《微观经济学：现代观点》第 32-33 章",
    "教材：平狄克《微观经济学》一般均衡部分",
    "软件工具：GeoGebra（用于绘制埃奇沃思框图）",
    "阅读材料：Arrow, K. J., & Debreu, G. (1954). Existence of an Equilibrium for a Competitive Economy."
  ]
}

{
  "teaching_material": {
    "topic": "Arrow's Impossibility Theorem",
    "subject_area": "Social Choice Theory / Economics / Political Science",
    "target_audience": "Undergraduate Students",
    "estimated_duration": "90 Minutes",
    "teaching_objectives": [
      "Students will be able to define the concept of a Social Welfare Function.",
      "Students will be able to list and explain Arrow's four fairness criteria (Unrestricted Domain, Non-Dictatorship, Pareto Efficiency, Independence of Irrelevant Alternatives).",
      "Students will understand the core statement of Arrow's Impossibility Theorem.",
      "Students will critically evaluate the limitations of voting systems in democratic processes."
    ],
    "key_points": [
      "The definition of Collective Decision Making and Preference Aggregation.",
      "Arrow's Four Axioms:\n1. Unrestricted Domain (Universality): The system must handle any possible set of individual preferences.\n2. Non-Dictatorship: No single voter should dictate the outcome.\n3. Pareto Efficiency (Weak Pareto): If everyone prefers A over B, society must prefer A over B.\n4. Independence of Irrelevant Alternatives (IIA): The ranking between A and B should depend only on individual rankings of A and B, not on other options.",
      "The Theorem Statement: No ranked voting system can satisfy all four criteria simultaneously when there are three or more alternatives.",
      "The distinction between 'Impossibility' and 'Inefficiency'."
    ],
    "difficulties": [
      "Understanding the abstract logical formulation of the Independence of Irrelevant Alternatives (IIA) condition.",
      "Grasping why the combination of these seemingly reasonable conditions leads to a logical contradiction.",
      "Distinguishing between Arrow's Theorem and the Condorcet Paradox (related but distinct concepts).",
      "Applying the theoretical constraints to practical voting scenarios (e.g., First-Past-The-Post vs. Ranked Choice)."
    ],
    "classroom_activity_design": {
      "phase_1_warm_up": {
        "title": "The Voting Paradox Introduction",
        "duration": "15 Minutes",
        "description": "Present a simple scenario with 3 voters and 3 candidates (A, B, C). Show how majority voting can lead to cyclical preferences (A > B, B > C, C > A), known as the Condorcet Paradox. Ask students: 'Is there a fair way to resolve this?'",
        "materials": "Whiteboard or Slide Deck"
      },
      "phase_2_instruction": {
        "title": "Explaining Arrow's Criteria",
        "duration": "30 Minutes",
        "description": "Lecture on the four axioms. Use analogies (e.g., comparing IIA to judging a race without considering disqualified runners). Walk through a simplified logical flow of why the theorem holds without heavy mathematical notation.",
        "materials": "Handout summarizing the 4 Axioms"
      },
      "phase_3_group_work": {
        "title": "Design Your Own System",
        "duration": "30 Minutes",
        "description": "Divide students into small groups. Task them with designing a voting rule that satisfies at least 3 of Arrow's 4 criteria. Have them test their rule against a hypothetical election dataset. Groups must identify which criterion they had to sacrifice.",
        "materials": "Worksheet with preference profiles"
      },
      "phase_4_discussion": {
        "title": "Implications for Democracy",
        "duration": "15 Minutes",
        "description": "Facilitate a class discussion. Does Arrow's Theorem mean democracy is impossible? How do real-world systems (like Approval Voting or Score Voting) navigate around the theorem?",
        "materials": "None"
      }
    },
    "assessment_methods": [
      "Formative: Observation during group work and participation in the final discussion.",
      "Summative: A short quiz asking students to identify which axiom is violated in a given voting scenario.",
      "Reflective: A 500-word essay on 'Is a Perfect Voting System Possible?'"
    ],
    "recommended_resources": [
      "Arrow, K. J. (1951). Social Choice and Individual Values.",
      "Sen, A. (1970). Collective Choice and Social Welfare.",
      "Video Lecture: 'Arrow's Impossibility Theorem' by Khan Academy or similar educational platforms."
    ]
  }
}

