{
  "teaching_material": {
    "title": "批判性分析建构主义教育理论",
    "knowledge_point": "Critical Analysis of Constructivist Theory in Education",
    "target_audience": "教育学专业本科生或在职教师培训",
    "duration": "90 分钟",
    "teaching_objectives": [
      {
        "dimension": "知识与理解",
        "description": "学生能够准确阐述建构主义的核心原则（如主动建构、社会互动、情境学习）及其主要流派（个人建构主义与社会建构主义）。"
      },
      {
        "dimension": "能力与应用",
        "description": "学生能够运用批判性思维，识别并评估建构主义教学策略在特定教学场景中的适用性与局限性。"
      },
      {
        "dimension": "情感与态度",
        "description": "培养学生对教育理论的辩证态度，避免盲目崇拜或全盘否定某种理论，形成基于证据的教学决策意识。"
      }
    ],
    "key_points": [
      "建构主义的核心理论基础（皮亚杰的认知发展、维果茨基的社会文化理论）。",
      "建构主义教学的优势：促进深度学习、提高学习动机、培养问题解决能力。",
      "对建构主义的批判性观点：认知负荷理论视角下的质疑（如 Kirschner 等人的最小指导教学争议）、实施难度、公平性问题及评估挑战。",
      "如何在直接教学与建构主义探究之间寻找平衡点（整合式教学）。"
    ],
    "difficulties": [
