        "expected_outcome": "学生能识别出缺乏支架（Scaffolding）的伪建构主义教学。"
      },
      {
        "activity_name": "辩论赛：'指导'还是'发现'？",
        "time_allocation": "30 分钟",
        "description": "正方：对于复杂概念的学习，直接指导优于建构主义探究；反方：建构主义探究更能培养高阶思维能力。要求双方引用实证研究支持观点。",
        "expected_outcome": "学生理解不同理论背后的证据基础，认识到情境依赖性。"
      },
      {
        "activity_name": "反思日志撰写",
        "time_allocation": "15 分钟",
        "description": "结合个人教学经验，写一段关于如何在本学科中平衡‘知识传授’与‘意义建构’的行动计划。",
        "expected_outcome": "内化批判性分析结果，形成个人教学哲学。"
      }
    ],
    "assessment_methods": [
      {
        "type": "形成性评价",
        "method": "课堂辩论参与度及案例诊断报告的准确性。"
      },
      {
        "type": "总结性评价",
        "method": "期末论文：选择一种当前流行的教学模式，用建构主义理论及其批判观点进行分析。"
      }
    ],
    "recommended_resources": [
