{
  "teaching_material": {
    "topic": "Negligence in Tort Law",
    "level": "Undergraduate / Introductory Law",
    "duration": "90 Minutes",
    "teaching_objectives": [
      {
        "id": 1,
        "description": "Students will be able to define negligence and explain its significance within the broader context of Tort Law."
      },
      {
        "id": 2,
        "description": "Students will identify and articulate the four essential elements required to prove a claim of negligence: Duty of Care, Breach of Duty, Causation, and Damages."
      },
      {
        "id": 3,
        "description": "Students will apply the 'Reasonable Person Standard' to hypothetical scenarios to determine if a breach of duty occurred."
      },
      {
        "id": 4,
        "description": "Students will analyze basic defenses to negligence, such as contributory negligence and voluntary assumption of risk."
      }
    ],
    "key_points": [
      {
        "point": "Definition of Negligence",
        "detail": "Failure to exercise the level of care that a reasonably prudent person would have exercised under the same circumstances."
      },
      {
        "point": "Duty of Care",
        "detail": "Legal obligation to avoid causing harm to others. Reference the 'Neighbour Principle' from Donoghue v Stevenson (1932)."
      },
      {
        "point": "Breach of Duty",
        "detail": "Determining if the defendant's conduct fell below the standard of care expected. Factors include probability of harm, severity of harm, and cost of precautions (Learned Hand Formula concept)."
      },
      {
        "point": "Causation",
        "detail": "Must establish Factual Causation ('But-For' Test) and Legal Causation (Remoteness/Proximate Cause)."
      },
      {
        "point": "Damages",
        "detail": "The plaintiff must have suffered actual loss or injury (physical, financial, or psychological) that is compensable."
      }
    ],
    "difficulties": [
      {
        "difficulty": "Distinguishing Factual vs. Legal Causation",
        "explanation": "Students often struggle to understand why an action can be factually linked to harm but legally too remote to warrant liability."
      },
      {
        "difficulty": "Applying the Reasonable Person Standard",
        "explanation": "Abstract nature of the 'reasonable person' makes it hard for students to apply objectively without personal bias."
      },
      {
        "difficulty": "Scope of Duty",
        "explanation": "Understanding when a duty exists (e.g., pure economic loss or psychiatric injury) versus when it does not."
      }
    ],
    "classroom_activity_design": [
      {
        "activity_name": "Case Study Analysis: The Slippery Floor",
        "type": "Group Discussion",
        "duration": "25 Minutes",
        "description": "Divide students into small groups. Provide a scenario where a customer slips in a grocery store. Groups must map the facts to the four elements of negligence.",
        "deliverable": "A completed 'Negligence Checklist' worksheet indicating whether each element is met based on the provided facts."
      },
      {
        "activity_name": "Role Play: The Courtroom Simulation",
        "type": "Simulation",
        "duration": "30 Minutes",
        "description": "Select two students to act as Plaintiff and Defendant counsel. They present arguments regarding the 'Breach of Duty' using the Reasonable Person Standard. Other students act as the Jury.",
        "deliverable": "Jury verdict and brief reasoning explaining their decision."
      },
      {
        "activity_name": "Defense Strategy Brainstorm",
        "type": "Individual/Paired Work",
        "duration": "15 Minutes",
        "description": "Present a scenario where the plaintiff was partially at fault. Ask students to draft a defense argument based on Contributory Negligence or Assumption of Risk.",
        "deliverable": "A 1-paragraph summary of the defense strategy."
      }
    ],
    "assessment_methods": [
      {
        "method": "Formative Assessment",
        "tool": "Exit Ticket",
        "question": "In one sentence, explain the difference between factual causation and legal causation."
      },
      {
        "method": "Summative Assessment",
        "tool": "Short Essay Question",
        "prompt": "Analyze a provided case scenario and argue whether a valid claim for negligence exists, addressing all four elements."
      }
    ],
    "required_resources": [
      "Textbook: Introduction to Tort Law (Chapter on Negligence)",
      "Case Law: Donoghue v Stevenson [1932] AC 562",
      "Handout: Negligence Element Checklist",
      "Projector for displaying hypothetical scenarios"
    ],
    "instructor_notes": [
      "Ensure students understand that negligence is about unreasonable conduct, not just accidental harm.",
      "Be prepared to clarify jurisdiction-specific variations (e.g., Comparative vs. Contributory Negligence).",
      "Encourage critical thinking over rote memorization of case names."
    ]
  }
}

