        "time_allocation": "20 Minutes"
      },
      {
        "activity_name": "Contract Modification Simulation",
        "description": "Pairs act as contractor and client. They must negotiate a price increase mid-project. The student acting as contractor must propose a new term that provides fresh consideration to make the increase binding.",
        "time_allocation": "15 Minutes"
      }
    ],
    "assessment_methods": [
      "Multiple Choice Quiz covering definitions and case outcomes.",
      "Short Answer Question: Explain why a promise to pay a gift is generally unenforceable due to lack of consideration."
    ],
    "required_resources": [
      "Standard Contract Law Textbook",
      "Handout summarizing Chappell & Co Ltd v Nestlé Co Ltd, Re McArdle, and Williams v Roffey Bros",
      "Projector for displaying case facts"
    ]
  }
}

