        "name": "Debate: Efficiency vs. Accountability",
        "type": "Class Debate",
        "duration": "20 Minutes",
        "steps": [
          "Motion: 'Strict bureaucratic procedures hinder effective policy implementation more than they protect public interest.'",
          "Split class into Pro and Con teams.",
          "Allow 5 minutes for preparation, 10 minutes for arguments, 5 minutes for closing statements."
        ]
      }
    },
    "assessment_methods": [
