      {
        "step": 1,
        "title": "Introduction & Lecture (20 mins)",
        "description": "Brief overview of PGx concepts and key enzyme pathways."
      },
      {
        "step": 2,
        "title": "Group Case Analysis (40 mins)",
        "description": "Students divided into groups receive a patient profile with genetic test results (e.g., CYP2C19 status) and a prescription history. They must recommend dosage adjustments or alternative therapies."
      },
      {
        "step": 3,
        "title": "Debate on Ethics (20 mins)",
        "description": "Structured debate: 'Should PGx testing be mandatory before prescribing high-risk medications?' Groups argue for and against."
      },
      {
        "step": 4,
        "title": "Summary & Q&A (10 mins)",
        "description": "Instructor summarizes key takeaways and clarifies misconceptions."
      }
    ]
  },
  "assessment_methods": [
    "Multiple-choice quiz on enzyme-substrate relationships.",
    "Written case study report evaluating treatment plans based on provided genomic data.",
    "Participation score during group discussions and debates."
  ],
  "recommended_resources": [
    "Clinical Pharmacogenetics Implementation Consortium (CPIC) Guidelines",
    "FDA Table of Pharmacogenomic Biomarkers in Drug Labeling",
    "Textbook: 'Pharmacogenomics: From Bench to Bedside'"
  ]
}

