{
  "teaching_material": {
    "topic": "Social Stratification and Class Systems",
    "subject": "Sociology / Social Studies",
    "target_audience": "High School Senior or Undergraduate Introductory Level",
    "estimated_duration": "90 Minutes (2 Class Periods)",
    "teaching_objectives": [
      "Students will be able to define social stratification and explain its universal yet variable nature.",
      "Students will differentiate between closed systems (e.g., Caste, Slavery) and open systems (e.g., Class).",
      "Students will analyze social stratification using Max Weber's three components: Class, Status, and Power.",
      "Students will evaluate the factors influencing social mobility and the impact of inequality on society."
    ],
    "key_points": [
      "Definition of Social Stratification: A system by which a society ranks categories of people in a hierarchy.",
      "Four Major Systems of Stratification: Slavery, Estate System, Caste System, Class System.",
      "Dimensions of Inequality: Economic (Wealth/Income), Political (Power), Social (Prestige/Prestige).",
      "Social Mobility: Vertical (up/down) and Horizontal movement; Intergenerational vs. Intragenerational.",
      "Theoretical Perspectives: Functionalism (Davis-Moore Thesis) vs. Conflict Theory (Marx)."
    ],
    "difficulties_and_challenges": [
      "Abstract Concepts: Students may struggle to distinguish between 'status' (social honor) and 'class' (economic position).",
      "Personal Bias: Students often view their own socioeconomic status as purely meritocratic, ignoring structural barriers.",
      "Intersectionality: Understanding how race, gender, and class overlap to create unique experiences of stratification.",
      "Global Perspective: Comparing stratification across different cultures and historical periods can be complex."
    ],
    "classroom_activity_design": [
      {
