{
  "teaching_material": {
    "topic": "Theoretical Perspectives on Social Institutions",
    "subject": "Sociology",
    "target_audience": "Undergraduate Students or Advanced High School",
    "estimated_duration": "90 Minutes",
    "teaching_objectives": [
      "Knowledge: Students will define 'social institutions' and identify the core tenets of Structural Functionalism, Conflict Theory, and Symbolic Interactionism.",
      "Skill: Students will be able to apply distinct theoretical frameworks to analyze specific social institutions (e.g., Family, Education, Religion).",
      "Value: Students will develop critical thinking skills by evaluating the strengths and limitations of each perspective regarding social order and change."
    ],
    "key_points": [
      "Definition of Social Institutions: Organized patterns of beliefs and behaviors centered on basic social needs.",
      "Structural Functionalism: Views society as a complex system whose parts work together to promote solidarity and stability; focuses on manifest and latent functions.",
      "Conflict Theory: Views society as an arena of inequality that generates conflict and change; focuses on power dynamics and resource distribution.",
      "Symbolic Interactionism: Focuses on face-to-face interaction and the subjective meanings individuals attach to social structures."
    ],
    "difficulties": [
      "Differentiating between Macro-level theories (Functionalism, Conflict) and Micro-level theory (Symbolic Interactionism).",
      "Understanding 'Latent Functions' (unintended consequences) versus 'Manifest Functions' (intended purposes).",
      "Applying Conflict Theory objectively without conflating personal political views with sociological analysis."
    ],
    "classroom_activity_design": [
      {
        "stage": "Warm-up (10 Minutes)",
        "activity_name": "Institution Identification",
        "description": "Teacher writes 'Society' on the board. Students brainstorm components (e.g., government, school, hospital). Teacher categorizes these as 'Social Institutions' and asks why they exist."
      },
      {
        "stage": "Instruction (25 Minutes)",
        "activity_name": "Theory Comparison Lecture",
        "description": "Interactive lecture using a Venn Diagram or Comparison Table. Use analogies: Functionalism = Human Body (organs working together); Conflict = Sports Game (winners vs. losers); Interactionism = Scripted Play (actors interpreting roles)."
      },
      {
        "stage": "Application (40 Minutes)",
        "activity_name": "Perspective Rotation Workshop",
        "description": "Divide class into 3 groups. Assign each group one theory. All groups analyze the SAME institution (e.g., Higher Education). Group 1 finds functions/stability. Group 2 finds inequality/power struggles. Group 3 finds student-teacher interactions/meanings. Groups rotate notes to critique each other."
      },
      {
        "stage": "Wrap-up (15 Minutes)",
        "activity_name": "Synthesis Discussion",
        "description": "Class discusses how combining all three perspectives provides a holistic view compared to using just one. Teacher summarizes key takeaways."
      }
    ],
    "assessment_methods": [
      "Formative: Observation of group participation during the Workshop.",
      "Summative: Short written assignment analyzing a news article using one of the three perspectives.",
      "Quiz: Multiple-choice questions distinguishing between the three theories."
    ],
    "required_resources": [
      "Projector and Slide Deck (including comparison charts).",
      "Printed Case Study Handouts (focusing on Education or Family).",
      "Whiteboard and Markers.",
      "Access to sociological journals or news articles for homework."
    ],
    "homework_extension": "Select a current social issue (e.g., tuition hikes, marriage laws). Write a 500-word essay analyzing the issue from two different theoretical perspectives."
  }
}

