      {
        "domain": "Comprehension",
        "goal": "Students will explain the biological mechanisms underlying cognitive recovery following brain injury."
      },
      {
        "domain": "Application",
        "goal": "Students will design a basic cognitive rehabilitation plan that leverages principles of neuroplasticity."
      },
      {
        "domain": "Evaluation",
        "goal": "Students will critically evaluate the efficacy of specific therapies based on current neuroplasticity research."
      }
