        "materials_needed": "Timer, debate rubric."
      }
    ],
    "assessment_methods": [
      {
        "type": "Formative",
        "method": "Exit Ticket: Students write down one mechanism of neuroplasticity and one example of its application in therapy before leaving class."
      },
      {
        "type": "Summative",
        "method": "Short Essay Assignment: Critique a specific cognitive rehabilitation program based on the five principles of neuroplastic training."
      }
    ],
    "recommended_resources": [
