    "assessment_methods": [
      {
        "type": "形成性评价",
        "method": "课堂参与度、辩论表现、角色扮演中的决策逻辑。"
      },
      {
        "type": "总结性评价",
        "method": "课后短文：‘为什么说威斯特伐利亚和约是现代国际法的基石？请列举三个理由。’（字数 300-500 字）"
