{
  "question": "What is the balanced chemical equation for the combustion of propane (C3H8) in the presence of oxygen (O2)?",
  "approach": {
    "description": "To balance the chemical equation for the combustion of propane, follow the law of conservation of mass ensuring the number of atoms for each element is equal on both the reactant and product sides.",
    "steps": [
      "Identify Reactants and Products: Propane (C3H8) reacts with Oxygen (O2) to form Carbon Dioxide (CO2) and Water (H2O).",
      "Write Unbalanced Equation: C3H8 + O2 -> CO2 + H2O.",
      "Balance Carbon (C): There are 3 Carbon atoms in C3H8, so place a coefficient of 3 before CO2.",
      "Balance Hydrogen (H): There are 8 Hydrogen atoms in C3H8, so place a coefficient of 4 before H2O (4 x 2 = 8).",
      "Balance Oxygen (O): Count Oxygen atoms on the right side (3x2 from CO2 + 4x1 from H2O = 10). Place a coefficient of 5 before O2 on the left side (5 x 2 = 10).",
      "Verification: Confirm 3 C, 8 H, and 10 O on both sides."
    ]
  },
  "final_balanced_equation": "C3H8 + 5O2 -> 3CO2 + 4H2O"
}

{
  "question": "What is the balanced chemical equation for the combustion of propane (C3H8)?",
  "approach_steps": [
    {
      "step_number": 1,
      "action": "Identify Reactants and Products",
      "details": "Combustion of a hydrocarbon involves reacting with oxygen (O2) to produce carbon dioxide (CO2) and water (H2O)."
    },
    {
      "step_number": 2,
      "action": "Write the Skeletal Equation",
      "details": "C3H8 + O2 -> CO2 + H2O"
    },
    {
      "step_number": 3,
      "action": "Balance Carbon Atoms",
      "details": "There are 3 Carbon atoms in C3H8. Place a coefficient of 3 before CO2."
    },
    {
      "step_number": 4,
      "action": "Balance Hydrogen Atoms",
      "details": "There are 8 Hydrogen atoms in C3H8. Place a coefficient of 4 before H2O (since 4 * 2 = 8)."
    },
    {
      "step_number": 5,
      "action": "Balance Oxygen Atoms",
      "details": "Count Oxygen on the product side: (3 * 2) + (4 * 1) = 10. Place a coefficient of 5 before O2 on the reactant side (since 5 * 2 = 10)."
    },
    {
      "step_number": 6,
      "action": "Verify Balance",
      "details": "Ensure the number of atoms for each element is equal on both sides."
    }
  ],
  "final_balanced_equation": "C3H8 + 5O2 -> 3CO2 + 4H2O"
}

