{
  "question": "Calculate the number of moles in 22 grams of carbon dioxide (CO2).",
  "approach": {
    "step_1": {
      "instruction": "Identify the given mass of the substance.",
      "data": "Mass (m) = 22 grams"
    },
    "step_2": {
      "instruction": "Calculate the molar mass of Carbon Dioxide (CO2).",
      "details": {
        "atomic_mass_carbon": "12 g/mol",
        "atomic_mass_oxygen": "16 g/mol",
        "calculation": "12 + (2 * 16) = 44 g/mol"
      },
      "result": "Molar Mass (M) = 44 g/mol"
    },
    "step_3": {
      "instruction": "Use the formula relating moles, mass, and molar mass.",
      "formula": "n = m / M",
      "where": {
        "n": "Number of moles",
        "m": "Mass in grams",
        "M": "Molar mass in grams per mole"
      }
    },
    "step_4": {
      "instruction": "Substitute the values and calculate.",
      "calculation": "n = 22 g / 44 g/mol",
      "result": "0.5"
    }
  },
  "final_answer": "0.5 moles"
}

