      {
        "step_number": 4,
        "action": "Determine Whole Number Subscripts",
        "instruction": "Examine the resulting ratios. If they are not whole numbers (e.g., 1.5, 1.33), multiply all ratios by a common integer to convert them into whole numbers."
      },
      {
        "step_number": 5,
        "action": "Write the Empirical Formula",
        "instruction": "Use the final whole numbers as subscripts for the corresponding element symbols to write the empirical formula."
      }
