{
  "question": "Evaluate the integral ∫ (3x^2 + 2x + 1) dx",
  "topic": "Indefinite Integration",
  "approach": "Term-by-Term Integration using the Power Rule",
  "rules_applied": [
    "Sum Rule: ∫ [f(x) + g(x)] dx = ∫ f(x) dx + ∫ g(x) dx",
    "Constant Multiple Rule: ∫ c * f(x) dx = c * ∫ f(x) dx",
    "Power Rule: ∫ x^n dx = (x^(n+1))/(n+1) + C, where n ≠ -1"
  ],
  "step_by_step_process": [
    {
      "step": 1,
      "description": "Separate the polynomial into individual terms.",
      "expression": "∫ 3x^2 dx + ∫ 2x dx + ∫ 1 dx"
    },
    {
      "step": 2,
      "description": "Apply the Power Rule to the first term (3x^2).",
      "calculation": "3 * (x^(2+1) / (2+1)) = 3 * (x^3 / 3) = x^3"
    },
    {
      "step": 3,
      "description": "Apply the Power Rule to the second term (2x).",
      "calculation": "2 * (x^(1+1) / (1+1)) = 2 * (x^2 / 2) = x^2"
    },
    {
      "step": 4,
      "description": "Apply the Power Rule to the constant term (1).",
      "calculation": "1 * (x^(0+1) / (0+1)) = x"
    },
    {
      "step": 5,
      "description": "Combine the integrated terms and add the constant of integration.",
      "result": "x^3 + x^2 + x + C"
    }
  ],
  "final_answer": "x^3 + x^2 + x + C"
}

