      ]
    },
    "phase_2_vector_analysis": {
      "description": "Analyze position and velocity vectors.",
      "actions": [
        "Draw position vectors r1 and r2 from the center to P1 and P2.",
        "Draw velocity vectors v1 and v2 tangent to the circle at P1 and P2.",
        "Note that the angle between r1 and r2 is equal to the angle between v1 and v2 due to perpendicularity."
      ]
    },
    "phase_3_geometric_relationship": {
      "description": "Use similar triangles to relate displacement and velocity change.",
      "actions": [
        "Form a triangle using position vectors (sides r, r, chord).",
        "Form a triangle using velocity vectors (sides v, v, delta_v).",
        "Establish similarity: |delta_v| / v = chord_length / r."
      ]
    },
    "phase_4_limit_process": {
      "description": "Apply calculus limits to find instantaneous acceleration.",
      "actions": [
        "Approximate chord_length as arc_length (s) for infinitesimal delta_t.",
