      {
        "step_number": 3,
        "action": "Substitute values",
        "description": "Insert T, ΔH°, and the converted ΔS° into the Gibbs-Helmholtz equation."
      },
      {
        "step_number": 4,
        "action": "Calculate",
        "description": "Compute the product TΔS° and subtract it from ΔH° to find ΔG°."
      }
    ]
  },
  "calculation_details": {
