  "proof_topic": "Lower Bound for Comparison-Based Sorting",
  "objective": "Prove that any comparison-based sorting algorithm has a time complexity lower bound of Omega(n log n) for sorting n distinct elements.",
  "methodology": "Decision Tree Model",
  "approach_steps": [
    {
      "step_number": 1,
      "concept": "Algorithm Representation",
      "action": "Model the sorting algorithm as a binary decision tree.",
      "explanation": "Each internal node represents a comparison between two elements (a:b), and each edge represents the outcome (a < b or a > b). Each path from root to leaf represents a sequence of comparisons."
    },
    {
      "step_number": 2,
      "concept": "Leaf Nodes and Permutations",
      "action": "Count the required number of leaf nodes.",
      "explanation": "There are n! possible permutations of n distinct elements. For the algorithm to be correct, every possible input permutation must lead to a unique leaf node representing the sorted order."
    },
    {
      "step_number": 3,
      "concept": "Tree Height and Worst Case",
      "action": "Relate tree height to the number of comparisons.",
      "explanation": "The worst-case number of comparisons performed by the algorithm is equal to the height (h) of the decision tree."
    },
    {
      "step_number": 4,
      "concept": "Binary Tree Property",
      "action": "Apply the property of binary trees regarding leaves.",
      "explanation": "A binary tree of height h can have at most 2^h leaves."
    },
    {
      "step_number": 5,
      "concept": "Inequality Derivation",
      "action": "Combine the permutation count and tree property.",
      "explanation": "Since the tree must have at least n! leaves, we establish the inequality: 2^h >= n!."
    },
    {
      "step_number": 6,
      "concept": "Logarithmic Analysis",
      "action": "Solve for h using logarithms.",
      "explanation": "Taking the base-2 logarithm of both sides yields: h >= log2(n!). Using Stirling's approximation, log2(n!) is Theta(n log n)."
    }
  ],
  "final_conclusion": "Since the height h represents the worst-case number of comparisons, and h >= log2(n!), the lower bound for any comparison-based sorting algorithm is Omega(n log n)."
}

