{
  "topic": "Market Equilibrium Calculation",
  "problem_statement": "Find the equilibrium price given Qd = 100 - 2P and Qs = 3P - 20.",
  "approach_steps": [
    {
      "step_number": 1,
      "concept": "Equilibrium Condition",
      "description": "In a perfectly competitive market, equilibrium is achieved when the quantity demanded (Qd) equals the quantity supplied (Qs)."
    },
    {
      "step_number": 2,
      "concept": "Algebraic Setup",
      "description": "Set the demand function equal to the supply function: 100 - 2P = 3P - 20."
    },
    {
      "step_number": 3,
      "concept": "Isolate Variable",
      "description": "Group the P terms on one side and the constant terms on the other. Add 2P to both sides and add 20 to both sides."
    },
    {
      "step_number": 4,
      "concept": "Solve for P",
      "description": "Divide the resulting total by the coefficient of P to determine the equilibrium price."
    }
  ],
