    },
    {
      "step_number": 3,
      "title": "Derive Marginal Revenue (MR)",
      "description": "Differentiate TR with respect to Q.",
      "calculation": "MR = d(TR)/dQ = 50 - Q"
    },
    {
      "step_number": 4,
      "title": "Equate MR and MC",
      "description": "Set MR equal to the given Marginal Cost.",
      "calculation": "50 - Q = 10"
    },
    {
      "step_number": 5,
      "title": "Solve for Optimal Quantity (Q*)",
      "description": "Isolate Q in the equation.",
      "calculation": "Q = 40"
    },
    {
      "step_number": 6,
      "title": "Solve for Optimal Price (P*)",
      "description": "Substitute Q* back into the Inverse Demand Function.",
      "calculation": "P = 50 - 0.5(40) = 30"
