{
  "approach": {
    "problem_type": "Intertemporal Consumer Choice",
    "goal": "Derive Intertemporal Budget Constraint and Euler Equation",
    "steps": [
      {
        "step_id": 1,
        "action": "Define Period-Specific Constraints",
        "instruction": "Write down the budget constraint for each period separately. For Period 1, consumption plus savings equals initial wealth (C1 + S = W). For Period 2, consumption equals accumulated savings plus interest (C2 = (1 + r)S)."
      },
      {
        "step_id": 2,
        "action": "Derive Intertemporal Budget Constraint (IBC)",
        "instruction": "Substitute the expression for savings (S) from the Period 1 constraint into the Period 2 constraint. Rearrange the equation to show that the present value of lifetime consumption equals initial wealth: C1 + C2/(1 + r) = W."
      },
