      {
        "element": "Consideration",
        "definition": "Something of value exchanged between the parties, which can be a benefit to the promisor or a detriment to the promisee.",
        "key_consideration": "Must be sufficient but need not be adequate; past consideration is generally invalid."
      },
      {
        "element": "Intention to Create Legal Relations",
        "definition": "The parties must demonstrate an intention for the agreement to be legally enforceable.",
        "key_consideration": "Presumed in commercial agreements; rebuttable in social/domestic agreements."
      },
      {
        "element": "Capacity",
        "definition": "The legal ability of the parties to enter into a contract.",
        "key_consideration": "Minors, persons of unsound mind, and intoxicated persons may lack capacity."
      },
      {
        "element": "Legality",
        "definition": "The subject matter and purpose of the contract must not be illegal or contrary to public policy.",
        "key_consideration": "Contracts involving criminal acts or fraud are void."
      }
    ],
    "conclusion": "All six elements must be present simultaneously for a valid contract to exist under common law principles."
  }
