{
  "approach_title": "Net Present Value (NPV) Project Selection Approach",
  "description": "This approach outlines the steps to evaluate Project A and Project B using the Net Present Value method to determine which investment adds more value to the company.",
  "steps": [
    {
      "step_number": 1,
      "action": "Identify Key Variables",
      "details": "Extract the initial investment, annual cash flow, duration (n), and cost of capital (r) for both projects. For Project A: Investment=$100k, CF=$30k, n=5, r=10%. For Project B: Investment=$150k, CF=$50k, n=5, r=10%."
    },
    {
      "step_number": 2,
      "action": "Determine the Present Value Factor",
      "details": "Since cash flows are equal annually, use the Present Value of an Annuity formula: PVIFA = [1 - (1 + r)^-n] / r. Calculate this factor for r=10% and n=5."
    },
    {
      "step_number": 3,
      "action": "Calculate NPV for Project A",
      "details": "Multiply the annual cash flow ($30,000) by the PVIFA calculated in Step 2 to get the total present value of inflows. Subtract the initial investment ($100,000) from this amount."
    },
    {
      "step_number": 4,
      "action": "Calculate NPV for Project B",
      "details": "Multiply the annual cash flow ($50,000) by the same PVIFA. Subtract the initial investment ($150,000) from this amount."
    },
    {
      "step_number": 5,
      "action": "Compare and Decide",
      "details": "Compare the resulting NPV figures. According to the NPV rule, select the project with the higher positive NPV, as it indicates greater wealth creation for shareholders."
    }
  ],
  "npv_formula": "NPV = (Annual Cash Flow × PVIFA(r, n)) - Initial Investment",
  "decision_rule": "Choose the project with the highest NPV. If both are negative, reject both. If mutually exclusive, choose the higher positive value."
}

