  "theory_overview": {
    "originator": "Leon Festinger",
    "year_published": 1957,
    "core_definition": "A psychological state of discomfort that occurs when an individual holds two or more contradictory beliefs, ideas, or values, or when their behavior contradicts their beliefs."
