  "mechanism_of_change": {
    "primary_driver": "Motivation to reduce psychological discomfort (dissonance) and restore internal consistency.",
    "sequence_of_events": [
      "Cognitive Conflict: An individual perceives an inconsistency between their current attitude/belief and their behavior or new information.",
      "Dissonance Arousal: This inconsistency creates psychological tension or anxiety.",
      "Motivation to Reduce: The individual feels compelled to eliminate or reduce this tension.",
      "Resolution Strategy: The individual alters their attitude or belief to align with their behavior, as changing behavior is often harder than changing a thought."
    ]
  },
  "methods_of_attitude_change": [
    {
      "method": "Direct Belief Modification",
      "description": "Changing the specific attitude to match the behavior (e.g., deciding a task was enjoyable after being paid little to do it)."
    },
    {
      "method": "Trivialization",
      "description": "Reducing the importance of the conflicting belief to minimize the impact of the dissonance."
    },
    {
      "method": "Adding Justifying Cognitions",
      "description": "Acquiring new information that supports the behavior, making the original belief seem less relevant."
    }
  ],
  "classroom_example": {
    "context": "Smoking Cessation",
    "initial_belief": "Smoking is dangerous to my health.",
    "conflicting_behavior": "Continues to smoke cigarettes daily.",
    "resulting_dissonance": "High psychological stress due to the contradiction.",
    "attitude_change_outcome": "To reduce stress without quitting, the individual may adopt the belief that 'the stress relief smoking provides is more important than long-term health risks,' thereby changing their attitude to justify the behavior."
  },
  "key_takeaway": "Cognitive dissonance theory suggests that attitude change is often a byproduct of the effort to maintain psychological consistency between what we do and what we think."
}

